        /**
         * Obtener un listado de los datos de las CC.
         * 
         * @param int       $inicio Inicio de la busqueda.
         * @param int       $limite Limite maximo de la busqueda.
         * @return array    Listado de los datos de las CC.
         */
        public static function obtenerListadoCuentas($inicio = 0, $limit = 10) {
          $mg=Doctrine_Manager::getInstance();
          $cont = 0;
          $conn=$mg->getCurrentConnection(); 
          $sql="SELECT DISTINCT dc.idcuenta , concat(dc.concatcta,'-', dc.descripcion) as cuenta, dc.descripcion,nc.tipo,nc.id
          from  mod_nomina.nom_cuentascierre nc
          inner join mod_contabilidad.nom_cuenta dc on (nc.idcuenta=dc.idcuenta)
          order by dc.idcuenta;"; //print_r($sql);die;
          $cuentas = $conn->fetchAll($sql); 
          $conn->commit(); //print_r($cuentas);die; 
         return $cuentas;
       }

