         public function findByIDOrDenom($idcuenta){
                  $query = Doctrine_Query::create();
                  $query->from('Nomcuentascierre')
                     ->Where("idcuenta = '$idcuenta'");
                  if (!empty($idcuenta)) {
                      $query->andWhere("idcuenta <> ?", $idcuenta);
                  }
                  $result = $query->count();
                  if ($result > 0) {
                      return true;
                  } else {
                      return false;
                  }
          }

          public static function obtenerOrdenDisponible()
          {
              $mg = Doctrine_Manager::getInstance();
              $conn = $mg->getCurrentConnection();
              $sql = "select MAX(cuenta) as orden from mod_nomina.nom_cuentascierre";
              $r = $conn->fetchAll($sql);
              $r[0]['cuenta'] = !empty($r) ? $r[0]['cuenta'] + 1 : 1;
              return $r[0];
          }
      
              
            
