    public static function obtenerDenomXId($idcuenta)
    {
      return Doctrine_Query::create()->select('p.cuenta AS cuenta')
        ->from('Nomcuentascierre p')
        ->where('p.idcuenta = ?', array($idcuenta))
        ->fetchOne()
        ->cuenta;
