    public static function existeDenominacion($idcuenta, $cuenta)
    {
      //Devolviendo la cantidad total de los salarios especificos.
      $query  = new Doctrine_Query ();
      $result = $query->from('Nomcuentascierre')
        ->where("cuenta like ?", array($cuenta));

      if (!empty($idcuenta)) {
        $query->addWhere("idcuenta <> ?", $idcuenta);
      }
      $result = $query->count();

      if ($result > 0) {
        return true;
      } else {
        return false;
      }
    }

   
    public static function esNeto($idcuenta)
    {
      $query  = new Doctrine_Query ();
      $result = $query->from('Nomcuentascierre p')
        ->where("p.cuenta = ?", array(1))
        ->andwhere("p.idcuenta = ?", array($idcuenta))
        ->setHydrationMode(Doctrine::HYDRATE_ARRAY)
        ->execute();
      if (count($result) > 0) {
        return true;
      } else {
        return false;
      }
    }
         
